/**
 * The theme page module, bound to every /themes/<id> by its asset key
 * (js/pages/themes/[id].js). The Desktop / Tablet / Phone switch stamps the
 * stage's data-mode, and the stage's width sets the --scale that fits the
 * 1440-wide desktop frame, which the tablet frame's sheet reads too. A
 * phone-sized window opens in phone mode.
 * No framework imports: the switch is the shared libs/pills.js.
 */
import { bindPills } from '../../libs/pills.js';

const DESKTOP_WIDTH = 1440;
const PHONE_WINDOW = '(max-width: 639.98px)';

export default async () => {
  const $stage = document.querySelector('[data-explorer-stage]');
  const $switch = document.querySelector('[data-explorer-switch]');

  const pressMode = bindPills($switch, (mode) => setMode(mode));
  const setMode = (mode) => {
    $stage.dataset.mode = mode;
    pressMode(mode);
  };

  new ResizeObserver(([entry]) => {
    $stage.style.setProperty('--scale', entry.contentRect.width / DESKTOP_WIDTH);
  }).observe($stage);

  if (window.matchMedia(PHONE_WINDOW).matches) {
    setMode('phone');
  }
};
